args = sys.argv[2:] if robustness_tests else sys.argv[1:]
features_result, feasibility = args[0], Path(args[1]).read_text().rstrip('\n')
text = HOST_RUN.read_text()
assert hashlib.sha256(text.encode()).hexdigest() == PRE, 'HOST_RUN.md is not the storage_limits version'

